// /* UTF-32 (Detect BOM) ------------------------------------------------------ */

// /*
//  * Detect a BOM at the beginning of the stream and select UTF-32BE or UTF-32LE
//  * accordingly.
//  *
//  * State values:
//  * 0    initial state
//  * 1    saw 00
//  * 2    saw 00 00
//  * 3    saw 00 00 FE
//  * 4    -
//  * 5    saw FF
//  * 6    saw FF FE
//  * 7    saw FF FE 00
//  * 8    UTF-32BE mode
//  * 9    UTF-32LE mode
//  *
//  * During detection: state&3==number of matching bytes so far.
//  *
//  * On output, emit U+FEFF as the first code point.
//  */
// U_CDECL_BEGIN
